import { fetchEventSource } from '@microsoft/fetch-event-source'

import { isMockEnabled } from './mock'
import {
  ApiRequestError,
  apiErrorFromResponse,
  notifyUnauthorized,
  refreshSession,
  resolveBaseUrl,
} from './client'
import type { ChatEventName, ChatStreamRequest, StreamHandlers } from '@/types'
import { storage } from '@/utils/storage'

/**
 * 比通用 `StreamHandlers` 多一个 `onClose`：`fetch-event-source` 的 `onclose`
 * 只在服务端正常关闭连接时触发，用于识别「静默关流但没收到 message.done」
 * 的断线（设计 4.2 B4），交给 store 的重连状态机处理。
 */
export interface ChatStreamHandlers extends StreamHandlers {
  onClose?: () => void
}

/**
 * SSE 事件白名单。新增 `ChatEventDataMap` 事件时必须同步加入，
 * 否则真实模式会在 onmessage 里被当作未知事件丢弃（mock 不经过这里）。
 */
export const CHAT_EVENT_NAMES = [
  'conversation.created',
  'run.started',
  'message.created',
  'message.started',
  'message.delta',
  'reasoning.delta',
  'reasoning.done',
  'skill.activated',
  'tool.start',
  'tool.result',
  'a2a.task',
  'a2a.artifact',
  'a2a.input_required',
  'a2a.auth_required',
  'approval.required',
  'run.interrupted',
  'run.resumed',
  'workflow.step',
  'memory.saved',
  'notice',
  'message.done',
  'error',
  'ping',
] as const satisfies readonly ChatEventName[]

const CHAT_EVENTS = new Set<ChatEventName>(CHAT_EVENT_NAMES)

export function isChatEvent(value: string): value is ChatEventName {
  return CHAT_EVENTS.has(value as ChatEventName)
}

async function readErrorBody(response: Response): Promise<unknown> {
  try {
    return await response.json()
  } catch {
    try {
      return await response.text()
    } catch {
      return null
    }
  }
}

async function connectOnce(
  payload: ChatStreamRequest,
  handlers: ChatStreamHandlers,
): Promise<void> {
  await fetchEventSource(`${resolveBaseUrl()}/chat/stream`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'text/event-stream',
      Authorization: `Bearer ${storage.getAccessToken() ?? ''}`,
    },
    body: JSON.stringify(payload),
    signal: handlers.signal,
    openWhenHidden: true,

    async onopen(response) {
      if (!response.ok) {
        // 409 run_in_progress / 403 capability_disabled 等错误体是 JSON 信封，
        // 必须在 onopen 里读出来，否则 fetch-event-source 只会抛 HTTP 状态。
        throw apiErrorFromResponse(response.status, await readErrorBody(response))
      }
      const contentType = response.headers.get('content-type') ?? ''
      if (!contentType.includes('text/event-stream')) {
        throw new ApiRequestError('SSE 响应不是 text/event-stream', {
          code: 'invalid_sse_response',
          status: response.status,
        })
      }
      handlers.onOpen?.(response.headers.get('X-Run-ID'))
    },

    onmessage(event) {
      if (!event.event || event.event === 'ping') return
      if (!isChatEvent(event.event)) {
        console.debug('[chat] 忽略未知事件', event.event)
        return
      }
      let data: unknown = {}
      if (event.data) {
        try {
          data = JSON.parse(event.data) as unknown
        } catch {
          console.warn('[chat] 无法解析 SSE 数据帧', event.data)
          return
        }
      }
      handlers.onEvent(event.event, data)
    },

    onerror(error) {
      if (error instanceof ApiRequestError) {
        // 交给外层统一处理（409 恢复、401 刷新），不要再回调 onError。
        throw error
      }
      handlers.onError(error instanceof Error ? error : new Error(String(error)))
      throw error
    },

    onclose() {
      handlers.onClose?.()
    },
  })
}

export async function openChatStream(
  payload: ChatStreamRequest,
  handlers: ChatStreamHandlers,
): Promise<void> {
  if (isMockEnabled()) {
    const { mockChatStream } = await import('@/api/mock/stream')
    await mockChatStream(payload, handlers)
    return
  }

  try {
    await connectOnce(payload, handlers)
  } catch (error) {
    if (error instanceof ApiRequestError && error.status === 401) {
      try {
        await refreshSession()
        await connectOnce(payload, handlers)
        return
      } catch (retryError) {
        if (retryError instanceof ApiRequestError && retryError.status === 401) {
          notifyUnauthorized()
        }
        throw retryError
      }
    }
    throw error

    pendingApprovalIds: pending,
    pendingApprovalId: pending[0] ?? null,
  }
}

/** 过期审批：卡片标记不可操作，并从待审列表移除。 */
export function markApprovalExpired(state: ChatState, approvalId: string): ChatState {
  const items = state.process.map((item) => {
    if (item.kind !== 'approval' || item.approvalId !== approvalId) return item
    return { ...item, status: 'canceled' } satisfies ApprovalProcess
  })
  const pending = state.pendingApprovalIds.filter((id) => id !== approvalId)
  return {
    ...state,
    process: items,
    pendingApprovalIds: pending,
    pendingApprovalId: pending[0] ?? null,
  }
}

/** 恢复执行意味着该 run 的所有 pending 审批都已处理，清理不可再操作的卡片。 */
export function markAllApprovalsResolved(state: ChatState): ChatState {
  const items = state.process.map((item) =>
    item.kind === 'approval' && item.status === 'waiting'
      ? ({ ...item, status: 'ok' } satisfies ApprovalProcess)
      : item,
  )
  return {
    ...state,
    process: items,
    pendingApprovalIds: [],
    pendingApprovalId: null,
  }
}

export function reduceChat(state: ChatState, event: ChatEventName, raw: unknown): ChatState {
  const data = asRecord(raw)
  const seq = typeof data.seq === 'number' ? data.seq : null
  if (seq !== null && seq <= state.lastSeq) return state

  const next: ChatState = {
    ...state,
    lastSeq: seq ?? state.lastSeq,
    process: [...state.process],
    messages: [...state.messages],
  }

  switch (event) {
    case 'ping':
      return state

    case 'conversation.created': {
      next.conversationId = str(data.conversation_id) || state.conversationId
      next.conversationTitle = str(data.title) || state.conversationTitle
      return next
    }

    case 'run.started': {
      next.conversationId = str(data.conversation_id) || state.conversationId
      next.runId = str(data.run_id) || state.runId
      next.runStatus = 'running'
      next.streaming = true
      next.finishReason = null
      next.error = null
      next.recovery = null
      next.usage = null
      next.pendingApprovalId = null
      next.pendingApprovalIds = []
      next.currentAssistantId = null
      next.process = []
      return next
    }

    case 'message.created': {
      const messageId = str(data.message_id)
      if (!messageId) return next
      const clientId = str(data.client_message_id)
      const index = clientId
        ? next.messages.findIndex((message) => message.client_message_id === clientId)
        : -1
      if (index >= 0) {
        const existing = next.messages[index]
        if (existing) {
          next.messages[index] = { ...existing, id: messageId, status: 'completed' }
        }
      } else {
        next.messages = [
          ...next.messages,
          {
            ...assistantMessage(messageId, next.runId, str(data.created_at) || undefined),
            role: 'user',
            streaming: false,
          },
        ]
      }
      return next
    }

    case 'message.started': {
      const messageId = str(data.message_id)
      if (!messageId) return next
      if (!next.messages.some((message) => message.id === messageId)) {
        next.messages = [
          ...next.messages,
          assistantMessage(messageId, next.runId, str(data.started_at) || undefined),
        ]
      }
      next.currentAssistantId = messageId
      return next
    }

    case 'message.delta': {
      const messageId = str(data.message_id)
      const delta = str(data.delta)
      if (!messageId || !delta) return next
      if (!next.messages.some((message) => message.id === messageId)) {
        next.messages = [...next.messages, assistantMessage(messageId, next.runId)]
      }
      next.messages = updateMessage(next.messages, messageId, (message) => ({
        ...message,
        content: message.content + delta,
        streaming: true,
      }))
      next.currentAssistantId = messageId
      next.streaming = true
      return next
    }

    case 'reasoning.delta': {
      const messageId = str(data.message_id)
      const delta = str(data.delta)
      if (!messageId || !delta) return next
      if (!next.messages.some((message) => message.id === messageId)) {
        next.messages = [...next.messages, assistantMessage(messageId, next.runId)]
      }
      next.messages = updateMessage(next.messages, messageId, (message) => ({
        ...message,
        reasoning: {
          content: (message.reasoning?.content ?? '') + delta,
          durationMs: message.reasoning?.durationMs ?? null,
          tokens: message.reasoning?.tokens ?? null,
          done: false,
        },
      }))
      return next
    }

    case 'reasoning.done': {
      const messageId = str(data.message_id)
      if (!messageId) return next
      next.messages = updateMessage(next.messages, messageId, (message) => ({
        ...message,
        reasoning: {
          content: message.reasoning?.content ?? str(data.summary),
          durationMs: numOrNull(data.duration_ms),
          tokens: numOrNull(data.tokens),
          done: true,
        },
      }))
      return next
    }

    case 'skill.activated': {
      const skillId = str(data.skill_id) || `skill-${next.lastSeq}`
      const item: SkillProcess = {
        kind: 'skill',
        id: `skill:${skillId}`,
        status: 'ok',
        startedAt: str(data.ts),
        durationMs: numOrNull(data.duration_ms),
        skillId,
        slug: str(data.slug),
        name: str(data.name) || str(data.slug),
        scope: str(data.scope),
        description: str(data.description),
        estimatedTokens: numOrNull(data.estimated_tokens),
      }
      next.process = upsertProcess(next.process, item)
      return next
    }

/** 成功与失败都记录一次请求，失败另记错误缓冲；记录本身不得影响请求。 */
function recordOutcome(
  config: InternalAxiosRequestConfig | undefined,
  status: number,
  headers: unknown,
): void {
  if (!config) return
  try {
    const requestId = headerValue(headers, 'x-request-id')
    recordRequest({
      method: String(config.method ?? 'get').toUpperCase(),
      url: String(config.url ?? ''),
      status,
      durationMs: elapsedMs(config),
      requestId,
      traceId: headerValue(headers, 'x-trace-id'),
      at: Date.now(),
    })
  } catch {
    // 诊断写入失败不影响业务请求。
  }
}

function toApiRequestError(error: unknown): ApiRequestError {
  if (axios.isAxiosError<ApiErrorBody>(error)) {
    const status = error.response?.status ?? 0
    if (error.response?.data) {
      return apiErrorFromResponse(status, error.response.data)
    }
    return new ApiRequestError(
      status === 0 ? '网络异常，请稍后重试' : error.message || '请求失败',
      { code: status === 0 ? 'network_error' : 'unknown_error', status },
    )
  }
  if (error instanceof ApiRequestError) {
    return error
  }
  return new ApiRequestError(error instanceof Error ? error.message : '请求失败', {
    code: 'unknown_error',
    status: 0,
  })
}

/** SSE 收到 401 且刷新失败时，通知外壳回到登录页。 */
export function notifyUnauthorized(): void {
  unauthorizedHandler?.()
}

export function createHttpClient(options: HttpClientOptions = {}): AxiosInstance {
  const client = axios.create({
    baseURL: options.baseURL ?? resolveBaseUrl(),
    timeout: 30_000,
    headers: { Accept: 'application/json' },
  })

  const refresh = options.refresh ?? refreshSession
  let refreshPromise: Promise<AuthTokens> | null = null

  async function refreshOnce(): Promise<AuthTokens> {
    if (!refreshPromise) {
      refreshPromise = refresh().finally(() => {
        refreshPromise = null
      })
    }
    return refreshPromise
  }

  function handleUnauthorized(): void {
    storage.clearTokens()
    options.onUnauthorized?.()
    if (!options.onUnauthorized) {
      unauthorizedHandler?.()
    }
  }

  client.interceptors.request.use((config) => {
    requestStartedAt.set(config, performance.now())
    const token = storage.getAccessToken()
    if (token) {
      config.headers.set('Authorization', `Bearer ${token}`)
    }
    return config
  })

  client.interceptors.response.use(
    (response) => {
      recordOutcome(response.config, response.status, response.headers)
      return response
    },
    async (error: unknown) => {
      const failed = toApiRequestError(error)
      if (axios.isAxiosError(error)) {
        recordOutcome(error.config, error.response?.status ?? 0, error.response?.headers)
      }
      try {
        const record = {
          code: failed.code,
          message: failed.message,
          requestId: failed.requestId,
          at: Date.now(),
        }
        recordError(record)
        reportError(record)
      } catch {
        // 诊断写入失败不影响业务错误处理。
      }
      if (!isUnauthorized(error)) {
        throw failed
      }

      const config = error.config as RetryableConfig | undefined
      const isRefreshRequest = config?.url?.includes('/auth/refresh')

      if (!config || config._retry || isRefreshRequest) {
        handleUnauthorized()
        throw toApiRequestError(error)
      }

      config._retry = true
      try {
        await refreshOnce()
        return await client.request(config)
      } catch {
        handleUnauthorized()
        throw new ApiRequestError('登录已过期，请重新登录', {
          code: 'unauthorized',
          status: 401,
        })
      }
    },
  )

  return client
}

export const apiClient = createHttpClient()
