# Agent Hub Web 生产环境 Nginx 配置（完整 nginx.conf）
#
# 用法：
#   1. 备份原 /etc/nginx/nginx.conf；
#   2. 按实际环境修改 upstream 地址与 root；
#   3. 用本文件替换 /etc/nginx/nginx.conf；
#   4. nginx -t && nginx -s reload。
#
# 注意：本文件是完整配置（含 events/http/server），不是 conf.d 片段。
# 若部署环境只允许投放 conf.d 片段，请把 server { ... } 拆出，并确保
# 主配置的 http 块内存在同名 upstream agent-hub-backend。

worker_processes auto;
pid /var/run/nginx.pid;
error_log /var/log/nginx/error.log warn;

events {
    worker_connections 1024;
    multi_accept on;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for" '
                    'rt=$request_time urt=$upstream_response_time';
    access_log /var/log/nginx/access.log main;

    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
    server_tokens off;

    # nginx 默认 1m 会直接把 >1 MB 的知识库上传挡成 413；前端上限是 10 MB，
    # 这里给 25m 留出 multipart 开销与后续上限调整的余量。
    client_max_body_size 25m;

    # 普通文本资源启用压缩；SSE 的 location 内单独 gzip off。
    gzip on;
    gzip_vary on;
    gzip_min_length 1024;
    gzip_types
        text/plain
        text/css
        text/javascript
        application/javascript
        application/json
        application/xml
        image/svg+xml;

    # 后端地址：容器编排中可改为服务名（如 agent-hub-backend:8000）。
    # keepalive 复用少量后端连接，降低普通 JSON 请求的握手开销。
    upstream agent-hub-backend {
        server 127.0.0.1:8000;
        keepalive 32;
    }

    server {
        listen 80;
        server_name _;

        root /usr/share/nginx/html;
        index index.html;

        # SPA fallback：真实文件优先；刷新前端路由时回落到 index.html。
        location / {
            try_files $uri $uri/ /index.html;
        }

        # 带内容哈希的构建产物：一年强缓存 + immutable，减少重复下载。
        # 文件名随内容变化，因此可以安全地使用长缓存。
        location /assets/ {
            expires 1y;
            add_header Cache-Control "public, immutable";
            access_log off;
            # 不存在的资源直接 404，避免 SPA fallback 把 index.html
            # 当成 JS/CSS 返回（会导致浏览器报 MIME 类型错误）。
            try_files $uri =404;
        }

        # 入口 HTML 不能长缓存，否则用户会一直拿到旧版本的 assets 引用。
        location = /index.html {
            add_header Cache-Control "no-cache";
        }

        # 知识库上传是同步入库（解析 + 切分 + embedding），可能超过 60s；
        # 单独放宽请求体与读写超时，避免 10 MB 文档在 nginx 层 413/504。
        location = /api/v1/knowledge/documents {
            proxy_pass http://agent-hub-backend;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Request-ID $request_id;
            proxy_set_header Connection "";
            proxy_connect_timeout 10s;
            client_max_body_size 25m;
            proxy_read_timeout 300s;
            proxy_send_timeout 300s;
        }

        # 普通 API 反代。聊天 SSE 有独立的精确 location（见下），
        # 不会受到这里 60s 读超时与默认缓冲的影响。
        location /api/ {
            proxy_pass http://agent-hub-backend;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Request-ID $request_id;
            proxy_set_header Connection "";
            proxy_connect_timeout 10s;
            proxy_read_timeout 60s;
            proxy_send_timeout 60s;
        }

        # 聊天流专用 SSE 端点（POST + text/event-stream）。
        # 精确匹配（=）优先于前缀匹配 /api/，因此这里的长连接参数是最终生效值。
        location = /api/v1/chat/stream {
            proxy_pass http://agent-hub-backend;

            # 使用 HTTP/1.1 与后端通信。HTTP/1.0 默认短连接、无 chunked，
            # 不适合长时间流式响应。
            proxy_http_version 1.1;

            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_set_header X-Request-ID $request_id;

            # 清除逐跳的 Connection 头（配合 HTTP/1.1 与 upstream keepalive），
            # 避免把 "Connection: close" 传给后端。
            proxy_set_header Connection "";

            # 关闭响应缓冲：后端每产生一个 SSE 事件就立即转发给浏览器，
            # 不攒满 proxy_buffer、也不等响应结束；这是逐帧流式输出的关键。
            proxy_buffering off;

            # 禁止缓存流式响应，避免中间层缓存半截事件或复用旧流。
            proxy_cache off;

            # 关闭 gzip：压缩器会引入额外缓冲，破坏事件到达的实时性；
            # SSE 文本本身很小，压缩收益也有限。
            gzip off;

            # 读超时放宽到 1 小时：模型可能长时间不产出下一个 chunk，
            # 默认 60s 会误判上游超时并返回 504、中断 SSE。
            proxy_read_timeout 3600s;

            # 写超时同样放宽：客户端网络慢时，给 nginx 足够时间写完事件。
            proxy_send_timeout 3600s;

            # 连接建立超时保持较短，后端不可用时快速失败。
            proxy_connect_timeout 10s;

            # 不覆盖上游 Content-Type；后端应返回 text/event-stream。
        }

        # 健康检查透传：供负载均衡/编排探活，不经过 SPA fallback。
        location = /healthz {
            proxy_pass http://agent-hub-backend/healthz;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header Connection "";
            access_log off;
        }

        location = /readyz {
            proxy_pass http://agent-hub-backend/readyz;
            proxy_http_version 1.1;
            proxy_set_header Host $host;
            proxy_set_header Connection "";
            access_log off;
        }
    }
