  approvalsApi: { decide: vi.fn(), list: vi.fn(), detail: vi.fn() },
}))

const emptyPage: PageResult<never> = { items: [], next_cursor: null, has_more: false }

function makeRun(overrides: Partial<Run> = {}): Run {
