    const rows = getRecentRequests()
    expect(rows[0]?.requestId).toBe('req-ok')
    expect(rows[0]?.traceId).toBe('trace-1')
    expect(rows[0]?.status).toBe(200)
    expect(rows[0]?.url).toBe('/anything')
