    const editable: AdminMcpServerUpdateRequest = {
      name: body.name,
      description: body.description,
      url: body.url,
      headers: body.headers,
      auto_inject: body.auto_inject,
      enabled: body.enabled,
      force_disabled: body.force_disabled,
