    }))
  }

  const adminUserMatch = /^\/admin\/users\/([^/]+)$/.exec(path)
  if (adminUserMatch) {
    const id = adminUserMatch[1]!
    if (method === 'GET') { ... }
    if (method === 'PATCH') {
      try { return ok(mockDb.adminUpdateUser(id, body)) }
      catch (error) { if (error instanceof MockAdminRuleError) return fail(error.status, error.code, error.message, error.details); throw error }
    }
  }
  ...
```

注意 `fail` 的 details 参数。`fail(status, code, message, details?)` 已支持。

需要导入 `MockAdminRuleError`（db 导出）。routers 已导入 mockDb from './db'；改为 `import { MockAdminRuleError, mockDb } from './db'`。

还需要一个 helper：`ruleResult(fn)`？直接 try/catch。

写全部端点。approvals 之前插入。

代码：

```ts
  // ---------- M8 管理台 ----------
  if (path === '/admin/overview' && method === 'GET') return ok(mockDb.adminOverview())
  if (path === '/admin/settings/instruction') {
    if (method === 'GET') return ok(mockDb.adminGetInstruction())
    if (method === 'PUT') {
      const content = body.content === undefined ? undefined : body.content
      if (content === undefined) return fail(422, 'validation_error', 'content 为必填字段')
      if (content !== null && typeof content !== 'string') return fail(422,'validation_error','content 必须为字符串或 null')
      try { return ok(mockDb.adminSaveInstruction(content)) } catch (e) { ... }
    }
  }
  if (path === '/admin/skills' && method === 'GET') return ok(mockDb.adminListSkills(stringParam(req.query,'q')))
  const skillEnabledMatch = /^\/admin\/skills\/([^/]+)\/enabled$/.exec(path)
  ...
  if (path === '/admin/mcp/servers') { GET/POST }
  const mcpMatch = /^\/admin\/mcp\/servers\/([^/]+)$/.exec(path)
  if (path === '/admin/agents') { GET }
  const agentMatch = /^\/admin\/agents\/([^/]+)$/.exec(path)
```

统一处理错误：

```ts
function handleRule<T>(fn: () => T): MockResult | T {
  try { return fn() } catch (error) {
    if (error instanceof MockAdminRuleError) {
      return fail(error.status, error.code, error.message, error.details)
    }
    throw error
  }
}
```
但返回类型混合麻烦。直接在每处 try/catch 转成 MockResult 更清晰。

为了减少重复，在 routers.ts 顶部加 helper：

```ts
function guarded(fn: () => MockResult): MockResult {
  try {
    return fn()
  } catch (error) {
    if (error instanceof MockAdminRuleError) {
      return fail(error.status, error.code, error.message, error.details)
    }
    throw error
  }
}
```

然后每个写端点 `return guarded(() => ok(mockDb.adminUpdateUser(...)!))`。若返回 null → 404。

